if (msg.statusCode !== 200) { node.error('HTTP '+msg.statusCode,msg); return null; }
const data=msg.payload;
const now=new Date();
if (!data || !Array.isArray(data.waitTime) || !data.waitTime.length || !data.updateTime || data.waitTime.some(r=>!r.hospName || !('t45p50' in r))) { node.error('AE schema changed',msg); return null; }
// updateTime is Hong Kong local time; never parse dd/mm via new Date(string).
const m=data.updateTime.match(/^(\d{2})\/(\d{2})\/(\d{4})\s+(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
if (!m) { node.error('Unknown source timestamp',msg); return null; }
let h=Number(m[4])%12+(m[6].toUpperCase()==='PM'?12:0);
const sourceTime=new Date(`${m[3]}-${m[2]}-${m[1]}T${String(h).padStart(2,'0')}:${m[5]}:00+08:00`);
if (!Number.isFinite(+sourceTime)) { node.error('Invalid source timestamp',msg); return null; }
const doc={_id:'ae:'+sourceTime.toISOString(), sourceTime, fetchedAt:now, sourceUrl:'https://www.ha.org.hk/opendata/aed/aedwtdata2-en.json', raw:data};
msg.view={...data,sourceISO:sourceTime.toISOString(),fetchedAt:now.toISOString()};
msg.payload=[{_id:doc._id},{$setOnInsert:doc,$set:{lastSeenAt:now}},{upsert:true}];
return msg;

if (msg.statusCode !== 200) { node.error('HTTP '+msg.statusCode,msg); return null; }
const data=msg.payload;
const now=new Date();
if (!Array.isArray(data) || !data.length || data.some(r=>!r.date_id_from || !r.date_id_to || !r.cluster || !r.specialty || !r.Category)) { node.error('SOP schema changed',msg); return null; }
// Row-level revision ID preserves corrections without treating daily polls as history.
msg.payload=[data.map(r=>{
 const id=JSON.stringify([r.date_id_from,r.date_id_to,r.cluster,r.specialty,r.Category,r.Description,r.Value]);
 return {updateOne:{filter:{_id:id},update:{$setOnInsert:{raw:r,fetchedAt:now,sourceUrl:'https://www.ha.org.hk/opendata/sop/sop-waiting-time-en.json'},$set:{lastSeenAt:now}},upsert:true}};
}),{ordered:false}];
return msg;

if(msg.statusCode!==200 || !Array.isArray(msg.payload)){node.error('Invalid hospital directory',msg);return null;}
const hospitals={};
for(const r of msg.payload){
 if(r.with_AE_service_eng!=='Yes') continue;
 const lat=Number(r.latitude),lon=Number(r.longitude);
 if(typeof r.institution_eng!=='string' || !Number.isFinite(lat)||!Number.isFinite(lon)||lat<22||lat>23||lon<113||lon>115){node.error('Invalid hospital coordinates',msg);return null;}
 hospitals[r.institution_eng]={lat,lon,cluster:r.cluster_eng,address:r.address_eng};
}
if(Object.keys(hospitals).length===0){node.error('Empty hospital directory',msg);return null;}
flow.set('haLocations',hospitals);
const view=flow.get('haLastView');if(!view)return null;
msg.payload={...view,locations:hospitals};return msg;

// MongoDB 8 aggregation: one observation per source timestamp and hospital.
const end = new Date();
const start = new Date(end.getTime() - 28 * 86400000);
msg.heatmapWindow = {start: start.toISOString(), end: end.toISOString()};
msg.payload = [[
  {$match: {sourceTime: {$gte: start, $lte: end}}},
  {$project: {sourceTime: 1, hospitals: '$raw.waitTime'}},
  {$unwind: '$hospitals'},
  {$project: {sourceTime: 1, hospital: '$hospitals.hospName', values: [
    {metric: 't3p50', raw: '$hospitals.t3p50'},
    {metric: 't3p95', raw: '$hospitals.t3p95'},
    {metric: 't45p50', raw: '$hospitals.t45p50'},
    {metric: 't45p95', raw: '$hospitals.t45p95'}
  ]}},
  {$unwind: '$values'},
  {$set: {parsed: {$regexFind: {input: {$ifNull: ['$values.raw', '']}, regex: '^(\\d+(?:\\.\\d+)?)\\s*(minute|hour)s?$', options: 'i'}}}},
  {$match: {parsed: {$ne: null}}},
  {$set: {minutes: {$multiply: [{$toDouble: {$arrayElemAt: ['$parsed.captures', 0]}}, {$cond: [{$eq: [{$toLower: {$arrayElemAt: ['$parsed.captures', 1]}}, 'hour']}, 60, 1]}]}}},
  {$group: {
    _id: {hospital: '$hospital', metric: '$values.metric', day: {$isoDayOfWeek: {date: '$sourceTime', timezone: 'Asia/Hong_Kong'}}, hour: {$hour: {date: '$sourceTime', timezone: 'Asia/Hong_Kong'}}},
    minutes: {$median: {input: '$minutes', method: 'approximate'}},
    samples: {$sum: 1}
  }},
  {$project: {_id: 0, hospital: '$_id.hospital', metric: '$_id.metric', day: '$_id.day', hour: '$_id.hour', minutes: 1, samples: 1}}
], {maxTimeMS: 20000}];
return msg;

const cells = msg.payload;
const {start, end} = msg.heatmapWindow;
const expected = {};
const step = 15 * 60000;
// Count source publication slots, rather than treating missing values as zero.
for (let time = Math.ceil(Date.parse(start) / step) * step; time <= Date.parse(end); time += step) {
  const local = new Date(time + 8 * 3600000);
  const day = local.getUTCDay() || 7;
  const key = `${day}:${local.getUTCHours()}`;
  expected[key] = (expected[key] || 0) + 1;
}
msg.payload = {
  cells,
  hospitals: [...new Set(cells.map(row => row.hospital))].sort(),
  expected,
  windowStart: start, windowEnd: end,
  generatedAt: new Date().toISOString()
};
return msg;

// Restore the latest persisted snapshot without fetching or writing a new record.
if (msg.topic && msg.topic !== 'ha-overview-request') return null;
msg.payload = [[
  {$sort: {sourceTime: -1}},
  {$limit: 1},
  {$project: {_id: 0, raw: 1, sourceTime: 1, fetchedAt: 1}}
], {maxTimeMS: 10000}];
return msg;

const snapshot = msg.payload?.[0];
if (!snapshot?.raw?.waitTime) return null;
const cached = flow.get('haLastView');
if (cached?.sourceISO && Date.parse(cached.sourceISO) > +new Date(snapshot.sourceTime)) return null;
msg.view = {...snapshot.raw, sourceISO: new Date(snapshot.sourceTime).toISOString(), fetchedAt: new Date(snapshot.fetchedAt || snapshot.sourceTime).toISOString()};
return msg;

// Seven days at source resolution; browser selectors filter without another query.
const end = new Date();
const start = new Date(end.getTime() - 7 * 86400000);
msg.historyWindow = {start: start.toISOString(), end: end.toISOString()};
msg.payload = [[
  {$match: {sourceTime: {$gte: start, $lte: end}}},
  {$sort: {sourceTime: 1}},
  {$project: {_id: 0, time: '$sourceTime', hospitals: '$raw.waitTime'}}
], {maxTimeMS: 20000}];
return msg;

// Include the current comparison in the replayed message so refresh restores both panels.
return {topic: 'ha-history', raw: flow.get('haChartView') || flow.get('haLastView'), payload: {
  snapshots: msg.payload,
  windowStart: msg.historyWindow.start,
  windowEnd: msg.historyWindow.end,
  generatedAt: new Date().toISOString()
}};
